window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b3b76f91e178fc49"]={"versions": [{"id": "FIG-b3b76f91e178fc49", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext des AUTOSAR Classic Platform Basissoftwaremoduls Synchronized Time-Base Manager (StbM). Das Diagramm veranschaulicht den Kontrollfluss und die Interaktionsabfolge bei der Offset-Ratenadaption (Offset Rate Adaption) zwischen einem busspezifischen Zeitsynchronisationsmodul, dem StbM und einer Time-Base-Consumer-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>«module» <code>&lt;Bus&gt;TSyn</code>: Busspezifisches Zeitsynchronisationsmodul (z. B. CanTSyn, FrTSyn, EthTSyn) als Zeitgeber-/Synchronisationsquelle.\n</li><li>«module» <code>StbM</code>: Synchronized Time-Base Manager als zentraler Verwalter synchronisierter Zeitbasen.\n</li><li>«SWC» <code>Active Customer</code>: Aktiver Konsument der Zeitbasis auf Applikationsebene.\n</li><li>Schnittstellenaufrufe / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>Synchronize()</code> von <code>&lt;Bus&gt;TSyn</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Calculate Rate For Rate Adaption“ mit Reflexivaufruf.\n</li><li>Synchroner Aufruf <code>Get Time()</code> (im Diagrammtext als <code>Get Time()</code>) von <code>Active Customer</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Correct Current Time with Rate Adaption Rate“ mit Reflexivaufruf.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei zeitlich getrennte Phasen:</p>\n<ol class=\"fig-list\"><li>Synchronisationsphase: <code>&lt;Bus&gt;TSyn</code> ruft synchron die Operation <code>Synchronize()</code> am <code>StbM</code> auf. Innerhalb des aktiven Ausführungsfokus führt der <code>StbM</code> eine interne Neuberechnung der Adaptionsrate aus („Calculate Rate For Rate Adaption“). Danach kehrt der Kontrollfluss via Antwortpfeil zu <code>&lt;Bus&gt;TSyn</code> zurück.\n</li><li>Zeitabfragephase: Ein <code>Active Customer</code> fragt über <code>Get Time()</code> die aktuelle Zeit beim <code>StbM</code> ab. Innerhalb des Ausführungsfokus korrigiert der <code>StbM</code> die aktuelle Zeitbasis anhand der zuvor ermittelten Adaptionsrate („Correct Current Time with Rate Adaption Rate“) und gibt den korrigierten Zeitwert an den Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das prinzipielle Zusammenspiel für die stetige Zeitanpassung über Offset-Raten. Entwickler von Basissoftware und SWCs müssen beachten, dass die Offset-Korrektur nicht sprunghaft, sondern adaptiv über die Rate erfolgt: Zeitaktualisierungen via <code>&lt;Bus&gt;TSyn</code> triggern die Ratenermittlung, während Konsumentenaufrufe (<code>Get Time()</code>) die Ratenkorrektur bei der Ausgabe anwenden, um Zeitsprünge für aktive Konsumenten zu vermeiden.</p>"}, {"id": "FIG-e7570770930dd9b2", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext des AUTOSAR Classic Platform Basissoftwaremoduls Synchronized Time-Base Manager (StbM). Das Diagramm veranschaulicht den Kontrollfluss und die Interaktionsabfolge bei der Offset-Ratenadaption (Offset Rate Adaption) zwischen einem busspezifischen Zeitsynchronisationsmodul, dem StbM und einer Time-Base-Consumer-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>«module» <code>&lt;Bus&gt;TSyn</code>: Busspezifisches Zeitsynchronisationsmodul (z. B. CanTSyn, FrTSyn, EthTSyn) als Zeitgeber-/Synchronisationsquelle.\n</li><li>«module» <code>StbM</code>: Synchronized Time-Base Manager als zentraler Verwalter synchronisierter Zeitbasen.\n</li><li>«SWC» <code>Active Customer</code>: Aktiver Konsument der Zeitbasis auf Applikationsebene.\n</li><li>Schnittstellenaufrufe / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>Synchronize()</code> von <code>&lt;Bus&gt;TSyn</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Calculate Rate For Rate Adaption“ mit Reflexivaufruf.\n</li><li>Synchroner Aufruf <code>Get Time()</code> (im Diagrammtext als <code>Get Time()</code>) von <code>Active Customer</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Correct Current Time with Rate Adaption Rate“ mit Reflexivaufruf.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei zeitlich getrennte Phasen:</p>\n<ol class=\"fig-list\"><li>Synchronisationsphase: <code>&lt;Bus&gt;TSyn</code> ruft synchron die Operation <code>Synchronize()</code> am <code>StbM</code> auf. Innerhalb des aktiven Ausführungsfokus führt der <code>StbM</code> eine interne Neuberechnung der Adaptionsrate aus („Calculate Rate For Rate Adaption“). Danach kehrt der Kontrollfluss via Antwortpfeil zu <code>&lt;Bus&gt;TSyn</code> zurück.\n</li><li>Zeitabfragephase: Ein <code>Active Customer</code> fragt über <code>Get Time()</code> die aktuelle Zeit beim <code>StbM</code> ab. Innerhalb des Ausführungsfokus korrigiert der <code>StbM</code> die aktuelle Zeitbasis anhand der zuvor ermittelten Adaptionsrate („Correct Current Time with Rate Adaption Rate“) und gibt den korrigierten Zeitwert an den Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das prinzipielle Zusammenspiel für die stetige Zeitanpassung über Offset-Raten. Entwickler von Basissoftware und SWCs müssen beachten, dass die Offset-Korrektur nicht sprunghaft, sondern adaptiv über die Rate erfolgt: Zeitaktualisierungen via <code>&lt;Bus&gt;TSyn</code> triggern die Ratenermittlung, während Konsumentenaufrufe (<code>Get Time()</code>) die Ratenkorrektur bei der Ausgabe anwenden, um Zeitsprünge für aktive Konsumenten zu vermeiden.</p>"}, {"id": "FIG-192eaaad55184007", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext des AUTOSAR Classic Platform Basissoftwaremoduls Synchronized Time-Base Manager (StbM). Das Diagramm veranschaulicht den Kontrollfluss und die Interaktionsabfolge bei der Offset-Ratenadaption (Offset Rate Adaption) zwischen einem busspezifischen Zeitsynchronisationsmodul, dem StbM und einer Time-Base-Consumer-Softwarekomponente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>«module» <code>&lt;Bus&gt;TSyn</code>: Busspezifisches Zeitsynchronisationsmodul (z. B. CanTSyn, FrTSyn, EthTSyn) als Zeitgeber-/Synchronisationsquelle.\n</li><li>«module» <code>StbM</code>: Synchronized Time-Base Manager als zentraler Verwalter synchronisierter Zeitbasen.\n</li><li>«SWC» <code>Active Customer</code>: Aktiver Konsument der Zeitbasis auf Applikationsebene.\n</li><li>Schnittstellenaufrufe / Nachrichten:\n<ul class=\"fig-list\"><li>Synchroner Aufruf <code>Synchronize()</code> von <code>&lt;Bus&gt;TSyn</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Calculate Rate For Rate Adaption“ mit Reflexivaufruf.\n</li><li>Synchroner Aufruf <code>Get Time()</code> (im Diagrammtext als <code>Get Time()</code>) von <code>Active Customer</code> an <code>StbM</code> inklusive gestrichelter Rückkehrantwort.\n</li><li>Interne Verarbeitungsnotiz am <code>StbM</code>: „Correct Current Time with Rate Adaption Rate“ mit Reflexivaufruf.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei zeitlich getrennte Phasen:</p>\n<ol class=\"fig-list\"><li>Synchronisationsphase: <code>&lt;Bus&gt;TSyn</code> ruft synchron die Operation <code>Synchronize()</code> am <code>StbM</code> auf. Innerhalb des aktiven Ausführungsfokus führt der <code>StbM</code> eine interne Neuberechnung der Adaptionsrate aus („Calculate Rate For Rate Adaption“). Danach kehrt der Kontrollfluss via Antwortpfeil zu <code>&lt;Bus&gt;TSyn</code> zurück.\n</li><li>Zeitabfragephase: Ein <code>Active Customer</code> fragt über <code>Get Time()</code> die aktuelle Zeit beim <code>StbM</code> ab. Innerhalb des Ausführungsfokus korrigiert der <code>StbM</code> die aktuelle Zeitbasis anhand der zuvor ermittelten Adaptionsrate („Correct Current Time with Rate Adaption Rate“) und gibt den korrigierten Zeitwert an den Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert das prinzipielle Zusammenspiel für die stetige Zeitanpassung über Offset-Raten. Entwickler von Basissoftware und SWCs müssen beachten, dass die Offset-Korrektur nicht sprunghaft, sondern adaptiv über die Rate erfolgt: Zeitaktualisierungen via <code>&lt;Bus&gt;TSyn</code> triggern die Ratenermittlung, während Konsumentenaufrufe (<code>Get Time()</code>) die Ratenkorrektur bei der Ausgabe anwenden, um Zeitsprünge für aktive Konsumenten zu vermeiden.</p>"}], "trans": [{"from": "FIG-b3b76f91e178fc49", "to": "FIG-e7570770930dd9b2", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e7570770930dd9b2", "to": "FIG-192eaaad55184007", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschnitt/Bildrahmen: Am oberen Bildrand ist eine Textzeile aus dem umliegenden Dokumententext sichtbar („...only be applied if Rate Correction is enabled, of course (refer to Figure 7.8).“). Die Diagramminhalte selbst sind unverändert.\n</li></ul>"}]};
